function detailModeFromParam(value: string | null): DetailMode {
  return value === "detail" ? "detail" : "overview";
}

function inspectorTargetFromSelection(streamKey: string | null, flowKey: string | null, interfaceKey: string | null): InspectorTarget | null {
  if (interfaceKey && !streamKey) return { kind: "interface", interfaceKey };
  if (!streamKey) return null;
  return flowKey ? { kind: "flow", streamKey, flowKey } : { kind: "stream", streamKey };
}

function inspectorMetricsQueryForRange(range: string, centerTimeSec: number | null): MetricsRangeQuery {
  const windowSec = timelineRangeWindowSec(range);
  if (windowSec === 300 && centerTimeSec === null) return { windowSec };
